"""Generador de la línea base inicial, NO ejecutar después de publicar migraciones.
Las migraciones resultantes se revisan y versionan; nunca se regenera una aplicada.
"""
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / 'supabase/migrations'
SCHEMAS = ['identidad', 'catalogo', 'comunidad', 'eventos', 'publicidad', 'recomendaciones', 'asistente']
META = "id uuid primary key default gen_random_uuid(), creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), version bigint not null default 1 check(version>0)"
tables = {s: [] for s in SCHEMAS}


def table(s, name, fields, meta=True):
    tables[s].append((name, f'create table {s}.{name} (\n  '+(META+',\n  ' if meta else '')+fields+'\n);'))


review = "estado text not null default 'borrador' check(estado in ('borrador','en_revision','publicado','rechazado','retirado'))"
coords = "lat numeric(9,6) check(lat between -90 and 90), lon numeric(9,6) check(lon between -180 and 180), check ((lat is null) = (lon is null))"
for s in ['identidad','catalogo','comunidad','eventos','publicidad']:
    table(s,'objeto',"propietario_id uuid not null, bucket text not null, clave_aleatoria text not null, mime_validado text, bytes bigint check(bytes>0), hash_integridad text, estado text not null default 'pendiente' check(estado in ('pendiente','validado','rechazado','retirado')), visibilidad text not null default 'privada' check(visibilidad in ('privada','publica')), padre_tipo text not null, padre_id uuid not null, unique(bucket,clave_aleatoria), check(visibilidad='privada' or estado='validado')")
table('identidad','perfil',"usuario_id uuid primary key, nombre_visible varchar(80) not null check(length(trim(nombre_visible))>0), biografia varchar(300) not null default '', avatar_id uuid references identidad.objeto(id), estado text not null default 'activo' check(estado in ('activo','suspendido','cerrado')), creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), version bigint not null default 1 check(version>0)",False)
table('identidad','asignacion_rol',"usuario_id uuid references identidad.perfil(usuario_id), rol text check(rol in ('turista','proveedor','administrador')), otorgado_por uuid not null, otorgado_en timestamptz not null default now(), primary key(usuario_id,rol)",False)
table('identidad','preferencia',"usuario_id uuid primary key references identidad.perfil(usuario_id), idioma varchar(10) not null default 'es', intereses jsonb not null default '[]' check(jsonb_typeof(intereses)='array'), perfil_visible boolean not null default false",False)
table('identidad','sesion_refresh',"usuario_id uuid not null references identidad.perfil(usuario_id), secreto_cifrado text not null check(length(secreto_cifrado)>0), vence_en timestamptz not null, revocada_en timestamptz, check(vence_en>creado_en)")
table('catalogo','destino',f"nombre varchar(120) not null, descripcion text not null default '', zona varchar(120) not null, {review}, unique(nombre,zona)")
table('catalogo','lugar',f"destino_id uuid not null references catalogo.destino(id), tipo text not null check(tipo in ('arqueologico','natural','cultural','camping','aventura','otro')), nombre varchar(120) not null, descripcion text not null, {coords}, {review}, fuente_url text, revisado_en timestamptz, condiciones_camping jsonb, check(estado<>'publicado' or revisado_en is not null)")
table('catalogo','negocio',f"propietario_id uuid not null, rubro text not null check(rubro in ('hospedaje','restaurante','artesania','transporte','operador','otro')), nombre varchar(120) not null, contacto jsonb not null default '{{}}' check(jsonb_typeof(contacto)='object'), {review}")
table('catalogo','oferta',f"negocio_id uuid not null references catalogo.negocio(id), tipo text not null, descripcion text not null, precio numeric(12,2) check(precio>=0), moneda char(3) not null check(moneda ~ '^[A-Z]{{3}}$'), unidad text not null check(unidad in ('persona','noche','tramo','grupo','paquete','producto')), vigencia_inicio timestamptz not null, vigencia_fin timestamptz not null, {review}, check(vigencia_fin>vigencia_inicio)")
table('catalogo','requisito_rubro',"rubro text not null, nombre varchar(120) not null, obligatorio boolean not null default true, version_politica integer not null check(version_politica>0), unique(rubro,nombre,version_politica)")
table('catalogo','evidencia',"negocio_id uuid not null references catalogo.negocio(id), requisito_id uuid references catalogo.requisito_rubro(id), objeto_id uuid not null references catalogo.objeto(id), estado text not null default 'pendiente' check(estado in ('pendiente','verificado','rechazado','vencido')), motivo_revision text, unique(negocio_id,id)")
table('catalogo','categoria_acreditada',"negocio_id uuid not null references catalogo.negocio(id), clase text not null check(clase in ('estrellas','tenedores','otra')), categoria varchar(80) not null, autoridad varchar(160) not null, evidencia_id uuid not null, estado text not null default 'pendiente' check(estado in ('pendiente','verificado','rechazado','vencido')), revisado_en timestamptz, vigente_hasta timestamptz, foreign key(negocio_id,evidencia_id) references catalogo.evidencia(negocio_id,id), check(estado<>'verificado' or revisado_en is not null)")
table('catalogo','punto_movilidad',f"destino_id uuid not null references catalogo.destino(id), lugar_id uuid references catalogo.lugar(id), tipo text not null check(tipo in ('terminal','punto_embarque')), nombre varchar(120) not null, direccion_publica text not null, {coords}, fuente text not null, revisado_en timestamptz, {review}, check(estado<>'publicado' or revisado_en is not null)")
table('catalogo','tramo_movilidad',"oferta_id uuid not null references catalogo.oferta(id), origen_id uuid not null references catalogo.punto_movilidad(id), destino_lugar_id uuid references catalogo.lugar(id), destino_texto text, horario_texto text not null, verificado_en timestamptz, check(destino_lugar_id is not null or length(trim(destino_texto))>0)")
table('catalogo','propuesta_lugar',"autor_id uuid not null, datos jsonb not null check(jsonb_typeof(datos)='object'), estado text not null default 'en_revision' check(estado in ('en_revision','aprobado','rechazado')), revisor_id uuid, motivo text, check(estado='en_revision' or revisor_id is not null)")
table('catalogo','favorito',"usuario_id uuid not null, objetivo_tipo text not null check(objetivo_tipo in ('lugar','negocio','oferta')), objetivo_id uuid not null, unique(usuario_id,objetivo_tipo,objetivo_id)")
table('comunidad','publicacion',f"autor_id uuid not null, destino_id uuid, objetivo_tipo text, objetivo_id uuid, texto text not null default '' check(length(texto)<=10000), {review}, publicado_en timestamptz, check((objetivo_tipo is null)=(objetivo_id is null)), check(estado<>'publicado' or publicado_en is not null)")
table('comunidad','comentario',f"autor_id uuid not null, objetivo_tipo text not null, objetivo_id uuid not null, padre_id uuid references comunidad.comentario(id), raiz_id uuid references comunidad.comentario(id), profundidad smallint not null default 0 check(profundidad between 0 and 5), texto text not null check(length(trim(texto)) between 1 and 3000), {review}, check(padre_id is null or padre_id<>id), check(raiz_id is null or raiz_id<>id), check((padre_id is null and raiz_id is null and profundidad=0) or (padre_id is not null and raiz_id is not null and profundidad>0))")
table('comunidad','like',"usuario_id uuid not null, objetivo_tipo text not null check(objetivo_tipo in ('foto','comentario','respuesta')), objetivo_id uuid not null, unique(usuario_id,objetivo_tipo,objetivo_id)")
table('comunidad','resena',f"usuario_id uuid not null, negocio_id uuid not null, puntuacion smallint not null check(puntuacion between 1 and 5), texto text not null, {review}")
table('comunidad','reporte',"autor_id uuid not null, objetivo_tipo text not null, objetivo_id uuid not null, motivo text not null, estado text not null default 'pendiente' check(estado in ('pendiente','resuelto','desestimado')), decision_administrativa text")
table('comunidad','contenido_cultural',f"tipo text not null check(tipo in ('historia','fotografia','libro','referencia')), titulo varchar(160) not null, cuerpo text, referencia text, autor_fuente text not null, destino_id uuid, {review}, check(cuerpo is not null or referencia is not null)")
table('comunidad','coleccion',"propietario_id uuid not null, nombre varchar(80) not null check(length(trim(nombre))>0), descripcion text")
table('comunidad','elemento_coleccion',"coleccion_id uuid not null references comunidad.coleccion(id), objetivo_tipo text not null, objetivo_id uuid not null, agregado_en timestamptz not null default now(), unique(coleccion_id,objetivo_tipo,objetivo_id)")
event_fields="organizador text not null, lugar_id uuid not null, inicio timestamptz not null, fin timestamptz not null, zona_horaria text not null default 'America/Lima', check(inicio<fin)"
table('eventos','propuesta',f"autor_id uuid not null, {event_fields}, fuente text not null, imagen_id uuid references eventos.objeto(id), estado text not null default 'en_revision' check(estado in ('en_revision','aprobado','rechazado')), motivo text")
table('eventos','evento',f"propuesta_id uuid references eventos.propuesta(id), titulo varchar(160) not null, {event_fields}, estado text not null default 'borrador' check(estado in ('borrador','confirmado','cancelado','finalizado')), version_publica bigint not null default 1 check(version_publica>0)")
table('eventos','suscripcion',"usuario_id uuid not null, tipo_objetivo text not null, objetivo_id uuid not null, recordatorio_config jsonb not null default '{}' check(jsonb_typeof(recordatorio_config)='object'), activa boolean not null default true, unique(usuario_id,tipo_objetivo,objetivo_id)")
task_key="usuario_id uuid not null, tipo text not null, objetivo_tipo text not null, objetivo_id uuid not null, version_objetivo bigint not null check(version_objetivo>0)"
table('eventos','tarea_recordatorio',f"{task_key}, ejecutar_en timestamptz not null, estado text not null default 'pendiente' check(estado in ('pendiente','procesando','enviado','cancelado','fallido')), lease_hasta timestamptz, unique(usuario_id,objetivo_tipo,objetivo_id,tipo,version_objetivo)")
table('eventos','notificacion',f"{task_key}, texto_resumen text not null, leida_en timestamptz, unique(usuario_id,objetivo_tipo,objetivo_id,tipo,version_objetivo)")
table('eventos','entrega',"notificacion_id uuid not null references eventos.notificacion(id), canal text not null check(canal in ('web','correo')), intento integer not null check(intento>0), estado text not null check(estado in ('pendiente','entregado','fallido')), error_tipado text, unique(notificacion_id,canal,intento)")
table('publicidad','politica_gratuita',"version_politica integer not null unique check(version_politica>0), habilitada boolean not null default true, duracion integer not null check(duracion>0), unidad text not null check(unidad in ('dias','meses')), condiciones jsonb not null check(jsonb_typeof(condiciones)='object'), aplica_desde timestamptz not null")
table('publicidad','beneficio',"negocio_id uuid not null unique, politica_version integer not null references publicidad.politica_gratuita(version_politica), condiciones_copiadas jsonb not null check(jsonb_typeof(condiciones_copiadas)='object'), inicio timestamptz not null, fin timestamptz not null, zona_horaria text not null default 'America/Lima', estado text not null check(estado in ('programado','activo','agotado','vencido','cancelado')), check(fin>inicio), unique(negocio_id,id)")
table('publicidad','plan',"nombre varchar(120) not null, tarifa numeric(12,2) not null check(tarifa>=0), moneda char(3) not null check(moneda ~ '^[A-Z]{3}$'), duracion integer not null check(duracion>0), unidad text not null check(unidad in ('dias','meses')), cuota bigint not null check(cuota>0), frecuencia integer not null check(frecuencia>0), peso_rotacion numeric(8,2) not null check(peso_rotacion>0), activo boolean not null default false")
table('publicidad','contratacion',"negocio_id uuid not null, plan_id uuid not null references publicidad.plan(id), condiciones_copiadas jsonb not null check(jsonb_typeof(condiciones_copiadas)='object'), inicio timestamptz not null, fin timestamptz not null, estado text not null default 'pendiente' check(estado in ('pendiente','vigente','vencida','cancelada')), check(fin>inicio), unique(negocio_id,id)")
table('publicidad','pago',"contratacion_id uuid not null references publicidad.contratacion(id), referencia_normalizada text not null unique check(length(trim(referencia_normalizada))>0), monto numeric(12,2) not null check(monto>0), moneda char(3) not null check(moneda ~ '^[A-Z]{3}$'), objeto_id uuid not null references publicidad.objeto(id), estado text not null default 'pendiente' check(estado in ('pendiente','confirmado','rechazado')), revisor_id uuid, motivo text, check(estado='pendiente' or revisor_id is not null)")
table('publicidad','campania',"negocio_id uuid not null, objetivo_tipo text not null, objetivo_id uuid not null, beneficio_id uuid, contratacion_id uuid, estado text not null default 'borrador' check(estado in ('borrador','en_revision','activa','pausada','agotada','finalizada','rechazada')), inicio timestamptz not null, fin timestamptz not null, creatividad_version bigint not null default 1 check(creatividad_version>0), check(fin>inicio), check(num_nonnulls(beneficio_id,contratacion_id)=1), foreign key(negocio_id,beneficio_id) references publicidad.beneficio(negocio_id,id), foreign key(negocio_id,contratacion_id) references publicidad.contratacion(negocio_id,id)")
table('publicidad','reserva_cuota',"campania_id uuid not null references publicidad.campania(id), solicitud_id uuid not null, usuario_medicion text, ventana_frecuencia timestamptz not null, vence_en timestamptz not null, estado text not null default 'reservada' check(estado in ('reservada','confirmada','liberada','vencida')), unique(campania_id,solicitud_id), check(vence_en>creado_en)")
table('publicidad','medicion',"entrega_id uuid not null, campania_id uuid not null references publicidad.campania(id), canal text not null, evento_tipo text not null check(evento_tipo in ('solicitud','entrega','impresion','clic')), sujeto_seudonimo text, instante timestamptz not null default now(), unique(entrega_id,evento_tipo)")
table('recomendaciones','viaje',"propietario_id uuid not null, criterios jsonb not null check(jsonb_typeof(criterios)='object'), desglose jsonb not null check(jsonb_typeof(desglose)='array'), total_estimado numeric(12,2) check(total_estimado>=0), moneda char(3) not null check(moneda ~ '^[A-Z]{3}$'), generado_en timestamptz not null default now()")
table('recomendaciones','proyeccion_oferta',"oferta_id uuid not null unique, version_fuente bigint not null check(version_fuente>0), resumen jsonb not null check(jsonb_typeof(resumen)='object'), actualizada_en timestamptz not null default now()")
table('asistente','conversacion',"propietario_id uuid not null, titulo varchar(160) not null, estado text not null default 'activa' check(estado in ('activa','cerrada','eliminada')), vence_retencion timestamptz not null, check(vence_retencion>creado_en)")
table('asistente','mensaje',"conversacion_id uuid not null references asistente.conversacion(id), rol text not null check(rol in ('usuario','asistente')), texto text not null, fuentes jsonb not null default '[]' check(jsonb_typeof(fuentes)='array'), modelo text")
table('asistente','documento_conocimiento',"fuente_tipo text not null, fuente_id uuid not null, version_fuente bigint not null check(version_fuente>0), visibilidad text not null check(visibilidad in ('publica','registrados')), contenido_reducido text not null, estado text not null check(estado in ('aprobado','retirado')), unique(fuente_tipo,fuente_id)")

for s in SCHEMAS:
    table(s,'auditoria',"actor_id uuid, accion text not null, objetivo_id uuid, campos_afectados text[] not null default '{}', motivo text, instante timestamptz not null default now(), request_id uuid")
    if s in ['catalogo','comunidad','eventos','publicidad']:
        table(s,'outbox',"tipo text not null, aggregate_id uuid not null, aggregate_version bigint not null check(aggregate_version>0), schema_version integer not null check(schema_version>0), payload jsonb not null check(jsonb_typeof(payload)='object'), ocurrido_en timestamptz not null default now(), publicado_en timestamptz, intentos integer not null default 0 check(intentos>=0)")
    if s != 'identidad':
        table(s,'inbox',"evento_id uuid primary key, recibido_en timestamptz not null default now(), procesado_en timestamptz",False)

OUT.mkdir(parents=True,exist_ok=True)
bootstrap=[]
for s in SCHEMAS:
    bootstrap += [f'create schema {s};', f'revoke all on schema {s} from public;', f"do $$ begin if not exists(select 1 from pg_roles where rolname='svc_{s}') then create role svc_{s} nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls; else raise exception 'El rol svc_{s} ya existe; revisar permisos antes de continuar'; end if; end $$;",f'grant usage on schema {s} to svc_{s};']
(OUT/'20261030000100_esquemas.sql').write_text('\n'.join(bootstrap)+'\n',encoding='utf-8')
for i,s in enumerate(SCHEMAS,2):
    body='\n\n'.join(sql for name,sql in tables[s])
    body+=f"\n\ncreate function {s}.actualizar_version() returns trigger language plpgsql set search_path='' as $$ begin new.actualizado_en=now(); new.version=old.version+1; return new; end $$;\nrevoke all on function {s}.actualizar_version() from public;\n"
    for name,sql in tables[s]:
        if 'actualizado_en' in sql:
            body+=f'create trigger actualizar_version before update on {s}.{name} for each row execute function {s}.actualizar_version();\n'
        body+=f'alter table {s}.{name} enable row level security;\nalter table {s}.{name} force row level security;\n'
    body+=f'revoke all on all tables in schema {s} from public;\nalter default privileges in schema {s} revoke all on tables from public;\nalter default privileges in schema {s} revoke execute on functions from public;\n'
    (OUT/f'20261030{i:04d}00_{s}.sql').write_text(body,encoding='utf-8')
print('Esquemas:',len(SCHEMAS),'Tablas:',sum(len(v) for v in tables.values()))
